export const getExportDiagnosticAnswersUrl = (params: ExportDiagnosticAnswersParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/diagnostics/answers.xlsx?${stringifiedParams}` : `/api/diagnostics/answers.xlsx`
}

